 p=ROOT/relative;s=p.read_text();assert s==(BASE/'Sources/Before'/relative).read_text();end=s.index(boundary);current,history=s[:end],s[end:]
 current=current.replace('selection-recovery R2','round-lifecycle-recovery R2').replace('selection recovery Android refresh R2','round lifecycle recovery Android refresh R2').replace('SelectionRecovery/R2AndroidRefresh','RoundLifecycleRecovery/R2AndroidRefresh').replace('linked selection R2','linked round lifecycle R2').replace('and49native-method','and61native-method').replace('766,023,250',size).replace('0c7c454dc83154e622fff646ac865a2c03fee5b5852ab5f46be24703bf48fb7a',h)
